import { sql } from 'drizzle-orm'
import { sqliteTable, text, integer, unique, index, check } from 'drizzle-orm/sqlite-core'

// ============================================================================
// COMPOSABLE COLUMN PRIMITIVES
// Change pricing logic = one edit. All line-item tables spread these.
// ============================================================================

/** Shared pricing contract for every line item in the system */
export const lineItemColumns = {
  lineType: text('line_type', { enum: ['part', 'labor', 'bicycle'] }).notNull(),
  partId: text('part_id').references(() => parts.id),
  laborServiceId: text('labor_service_id').references(() => laborServices.id),
  description: text('description').notNull(),
  quantity: integer('quantity', { mode: 'number' }).notNull().default(1),
  unitPriceNet: integer('unit_price_net', { mode: 'number' }).notNull(), // ex-tax cents per unit
  vatRateId: text('vat_rate_id').references(() => vatRates.id).notNull(), // FK to vatRates lookup
  discountPercent: integer('discount_percent'), // basis points, nullable = no discount
  lineTotalNet: integer('line_total_net', { mode: 'number' }).notNull(), // discounted net total
  lineTotalVat: integer('line_total_vat', { mode: 'number' }).notNull(), // VAT amount
  lineTotalGross: integer('line_total_gross', { mode: 'number' }).notNull(), // incl-tax total
}

/** Bicycle-specific details for bicycle line items */
export const bicycleLineColumns = {
  bicycleId: text('bicycle_id').references(() => bicycles.id), // link to physical instance
  bicycleBrand: text('bicycle_brand'),
  bicycleModel: text('bicycle_model'),
  bicycleYear: integer('bicycle_year', { mode: 'number' }),
  bicycleColor: text('bicycle_color'),
  bicycleFrameSize: text('bicycle_frame_size'),
}

/** CHECK constraints for line item tables — applied per-table via extras callback */
export const lineItemChecks = () => ({
  totalsNonNegative: check(
    'line_totals_non_negative',
    sql`${sql.identifier('line_total_net')} >= 0 AND ${sql.identifier('line_total_vat')} >= 0 AND ${sql.identifier('line_total_gross')} >= 0`
  ),
})

// ============================================================================
// CORE ENTITIES — Customers, Staff, Tax
// ============================================================================

/** Who we serve — private individuals or companies. Anonymous walk-ins have no row. */
export const customers = sqliteTable('customers', {
  id: text('id').primaryKey(),
  type: text('type', { enum: ['private', 'company'] }).notNull().default('private'),
  firstName: text('first_name'), // required for private
  lastName: text('last_name'), // required for private
  companyName: text('company_name'), // required for company
  vatId: text('vat_id'), // for companies
  phone: text('phone'),
  email: text('email'),
  street: text('street'),
  number: text('number'),
  bus: text('bus'),
  postalCode: text('postal_code'),
  city: text('city'),
  country: text('country').notNull().default('BE'), // Belgium default
  notificationPreference: text('notification_preference', { enum: ['sms', 'email'] }),
})

export type Customer = typeof customers.$inferSelect
export type NewCustomer = typeof customers.$inferInsert

/** Shop staff — mechanics and managers with hourly rates */
export const users = sqliteTable('users', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  role: text('role', { enum: ['mechanic', 'manager'] }).notNull().default('mechanic'),
  hourlyRate: integer('hourly_rate', { mode: 'number' }).notNull(),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
})

export type User = typeof users.$inferSelect
export type NewUser = typeof users.$inferInsert

/** VAT rate lookup — e.g. standard 21%, reduced 6% */
export const vatRates = sqliteTable('vat_rates', {
  id: text('id').primaryKey(),
  rate: integer('rate').notNull().unique(), // basis points: 2100 = 21%, 600 = 6%
  description: text('description').notNull(),
})

export type VatRate = typeof vatRates.$inferSelect
export type NewVatRate = typeof vatRates.$inferInsert

// ============================================================================
// CATALOG — Parts, Labor Services, Bicycle Templates
// ============================================================================

/** Physical products with stock tracking */
export const parts = sqliteTable('parts', {
  id: text('id').primaryKey(),
  barcode: text('barcode').notNull().unique(),
  name: text('name').notNull(),
  description: text('description'),
  priceNet: integer('price_net', { mode: 'number' }).notNull(), // ex-tax cents
  costPrice: integer('cost_price', { mode: 'number' }), // in cents
  quantityOnHand: integer('quantity_on_hand', { mode: 'number' }).notNull().default(0),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
}, (table) => ({
  activeIdx: index('parts_active_idx').on(table.isActive),
}))

export type Part = typeof parts.$inferSelect
export type NewPart = typeof parts.$inferInsert

/** Labor services — hourly or fixed-rate work types */
export const laborServices = sqliteTable('labor_services', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  description: text('description'),
  billingType: text('billing_type', { enum: ['hourly', 'fixed'] }).notNull(),
  defaultRate: integer('default_rate', { mode: 'number' }).notNull(), // cents/hour or fixed amount
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
})

export type LaborService = typeof laborServices.$inferSelect
export type NewLaborService = typeof laborServices.$inferInsert

/** Bicycle catalog templates — become real bicycles when sold or taken in */
export const bicycleTemplates = sqliteTable('bicycle_templates', {
  id: text('id').primaryKey(),
  brand: text('brand').notNull(),
  model: text('model').notNull(),
  description: text('description'),
  basePriceNet: integer('base_price_net', { mode: 'number' }), // optional catalog price in cents
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
})

export type BicycleTemplate = typeof bicycleTemplates.$inferSelect
export type NewBicycleTemplate = typeof bicycleTemplates.$inferInsert

// ============================================================================
// BICYCLES — Physical Instances
// ============================================================================

/** Real bicycles — customer-owned or shop inventory */
export const bicycles = sqliteTable('bicycles', {
  id: text('id').primaryKey(),
  source: text('source', { enum: ['inventory', 'customer_owned'] }).notNull().default('customer_owned'),
  templateId: text('template_id').references(() => bicycleTemplates.id), // nullable for customer-owned
  customerId: text('customer_id').references(() => customers.id), // required when source = 'customer_owned'
  brand: text('brand').notNull(), // snapshotted from template or entered manually
  model: text('model').notNull(),
  year: integer('year', { mode: 'number' }),
  color: text('color'),
  frameSize: text('frame_size'),
  status: text('status', { enum: ['inventory', 'in_shop', 'ready_for_pickup', 'returned', 'sold'] })
    .notNull().default('inventory'),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  customerIdIdx: index('bicycles_customer_id_idx').on(table.customerId),
  sourceCustomerCheck: check(
    'bicycles_source_customer_check',
    sql`(${sql.identifier('source')} = 'customer_owned' AND ${sql.identifier('customer_id')} IS NOT NULL) OR (${sql.identifier('source')} = 'inventory' AND ${sql.identifier('customer_id')} IS NULL)`
  ),
}))

export type Bicycle = typeof bicycles.$inferSelect
export type NewBicycle = typeof bicycles.$inferInsert

// ============================================================================
// WORKING DOCUMENTS — Quotes, Repairs, Customer Orders, Backorders
// ============================================================================

/** Estimates/proposals — immutable once sent. Copied to Order or Repair on approval. */
export const quotes = sqliteTable('quotes', {
  id: text('id').primaryKey(),
  quoteNumber: text('quote_number').notNull().unique(), // QT-0001
  customerId: text('customer_id').references(() => customers.id), // nullable during draft
  status: text('status', { enum: ['draft', 'sent', 'converted', 'rejected'] })
    .notNull().default('draft'),
  notes: text('notes'),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  statusIdx: index('quotes_status_idx').on(table.status),
  customerRequiredCheck: check(
    'quotes_customer_required_check',
    sql`${sql.identifier('status')} = 'draft' OR ${sql.identifier('customer_id')} IS NOT NULL`
  ),
}))

export type Quote = typeof quotes.$inferSelect
export type NewQuote = typeof quotes.$inferInsert

/** Quote line items — snapshotted pricing per line */
export const quoteLineItems = sqliteTable('quote_line_items', {
  id: text('id').primaryKey(),
  quoteId: text('quote_id').notNull().references(() => quotes.id),
  ...lineItemColumns,
  ...bicycleLineColumns,
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  quoteIdIdx: index('quote_line_items_quote_id_idx').on(table.quoteId),
  ...lineItemChecks(),
}))

export type QuoteLineItem = typeof quoteLineItems.$inferSelect
export type NewQuoteLineItem = typeof quoteLineItems.$inferInsert

// ---------------------------------------------------------------------------
/** Repair work tracking — links bicycle, worker, and line items */
export const repairs = sqliteTable('repairs', {
  id: text('id').primaryKey(),
  bicycleId: text('bicycle_id').notNull().references(() => bicycles.id),
  assignedTo: text('assigned_to').references(() => users.id),
  status: text('status', { enum: ['intake', 'in_progress', 'on_hold', 'ready', 'completed', 'cancelled'] })
    .notNull().default('intake'),
  customerNotes: text('customer_notes'),
  internalNotes: text('internal_notes'), // technician observations during work
  holdReason: text('hold_reason', { enum: ['waiting_parts', 'awaiting_customer_approval', 'other'] }),
  holdReasonNote: text('hold_reason_note'),
  plannedDate: integer('planned_date', { mode: 'timestamp' }), // scheduled start/completion date
  pickupDate: integer('pickup_date', { mode: 'timestamp' }), // customer collection date
  completedAt: integer('completed_at', { mode: 'timestamp' }),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  statusIdx: index('repairs_status_idx').on(table.status),
  holdReasonNoteCheck: check(
    'repairs_hold_reason_note_check',
    sql`${sql.identifier('hold_reason')} IS NULL OR ${sql.identifier('hold_reason_note')} IS NOT NULL`
  ),
}))

export type Repair = typeof repairs.$inferSelect
export type NewRepair = typeof repairs.$inferInsert

/** Repair line items — parts used and labor logged. minutesWorked is billing-specific; workLogs is the source of truth for actual time worked (payroll). */
export const repairLineItems = sqliteTable('repair_line_items', {
  id: text('id').primaryKey(),
  repairId: text('repair_id').notNull().references(() => repairs.id),
  ...lineItemColumns,
  minutesWorked: integer('minutes_worked', { mode: 'number' }), // billing minutes; may differ from workLogs (payroll)
  hourlyRateSnapshot: integer('hourly_rate_snapshot', { mode: 'number' }), // worker's rate at time of logging
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  repairIdIdx: index('repair_line_items_repair_id_idx').on(table.repairId),
  ...lineItemChecks(),
}))

export type RepairLineItem = typeof repairLineItems.$inferSelect
export type NewRepairLineItem = typeof repairLineItems.$inferInsert

/** Timer sessions per repair — source of truth for actual time worked (payroll). Billing minutes are in repairLineItems. */

import { Hono } from 'hono'
import {
  createRepairIntake,
  getRepairsList,
  getRepairById,
  transitionRepairStatus,
  updateRepairNotes,
  getCustomerWithBicycles,
  createRepairLineItem,
  updateRepairLineItem,
  deleteRepairLineItem,
  listLaborServices,
  assignWorkerToRepair,
  startWorkTimer,
  stopWorkTimer,
  completeRepairPayment,
  type RepairDetail,
  type RepairStatus,
} from '../services/repair.service.js'

const repairsRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /repairs — Paginated list of repairs with filtering and sorting
//
// Query params:
//   status       - Filter by status (intake, in_progress, on_hold, verified, ready, completed, cancelled)
//   assignedTo   - Filter by worker ID or 'unassigned' for NULL assignments
//  pickupDate    - Filter by pickup date: 'today' or 'this_week'
//   page         - Page number (1-indexed, default 1)
//   pageSize     - Items per page (default 20)
//
// Default sort: planned_date DESC (most urgent first), then created_at DESC
// ---------------------------------------------------------------------------

repairsRoutes.get('/', async (c) => {
  const status = c.req.query('status') as string | undefined
  const assignedToRaw = c.req.query('assignedTo') as string | undefined
  const pickupDateFilter = c.req.query('pickupDate') as 'today' | 'this_week' | undefined
  const page = parseInt(c.req.query('page') || '1', 10)
  const pageSize = Math.min(parseInt(c.req.query('pageSize') || '20', 10), 100) // cap at 100

  // Build filters
  const filters: Parameters<typeof getRepairsList>[0] = {}

  if (status && ['intake', 'in_progress', 'on_hold', 'verified', 'ready', 'completed', 'cancelled'].includes(status)) {
    filters.status = status as RepairStatus
  }

  if (assignedToRaw === 'unassigned') {
    filters.assignedTo = null
  } else if (assignedToRaw) {
    filters.assignedTo = assignedToRaw
  }

  if (pickupDateFilter && ['today', 'this_week'].includes(pickupDateFilter)) {
    filters.pickupDateFilter = pickupDateFilter
  }

  const result = await getRepairsList(filters, page, pageSize)
  return c.json(result)
})

// ---------------------------------------------------------------------------
// POST /repairs — Create a new repair via intake flow
//
// Accepts customer (search existing or create inline), bicycle (select from
// customer's bikes or create inline with brand/model/color), and notes.
// Repairs are created with status='intake' and assignedTo=NULL.
// ---------------------------------------------------------------------------

repairsRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    const repair = await createRepairIntake(input)
    return c.json(repair, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    // Zod validation error or business logic error
    const message = err instanceof Error ? err.message : 'Validation failed'
    const status = (err as { code?: string; name?: string }).code === 'NOT_FOUND' || (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// GET /repairs/:id — Get single repair detail
// ---------------------------------------------------------------------------

repairsRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')
  const repair = await getRepairById(id)

  if (!repair) {
    return c.json({ error: 'Repair not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json(repair)
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/status — Transition repair status (canonical endpoint)
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/status', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const repair = await transitionRepairStatus(id, input)
    return c.json(repair as RepairDetail)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Transition failed'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/transition — Legacy alias for backward compatibility
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/transition', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const repair = await transitionRepairStatus(id, input)
    return c.json(repair as RepairDetail)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Transition failed'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/notes — Update repair notes
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/notes', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const repair = await updateRepairNotes(id, input)
    return c.json(repair as RepairDetail)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Update failed'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// GET /repairs/customers/:customerId — Get customer with bicycles for intake
// ---------------------------------------------------------------------------

repairsRoutes.get('/customers/:customerId', async (c) => {
  const customerId = c.req.param('customerId')
  const customerWithBicycles = await getCustomerWithBicycles(customerId)

  if (!customerWithBicycles) {
    return c.json({ error: 'Customer not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json(customerWithBicycles)
})

// ---------------------------------------------------------------------------
// GET /labor-services — List available labor services catalog
// ---------------------------------------------------------------------------

repairsRoutes.get('/labor-services', async (c) => {
  const billingType = c.req.query('billingType') as 'hourly' | 'fixed' | undefined

  try {
    const services = await listLaborServices(billingType ? { billingType } : {})
    return c.json(services)
  } catch (err) {
    console.error('[GET /labor-services] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Failed to fetch labor services', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// POST /repairs/:id/items — Create a line item (part or labor)
// ---------------------------------------------------------------------------

repairsRoutes.post('/:id/items', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const item = await createRepairLineItem(id, input)
    return c.json(item, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to create line item'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' || (err as { name?: string }).name === 'RepairCompletedError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/items/:itemId — Update a line item
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/items/:itemId', async (c) => {
  const id = c.req.param('id')
  const itemId = c.req.param('itemId')
  const input = await c.req.json()

  try {
    const item = await updateRepairLineItem(id, itemId, input)
    return c.json(item)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to update line item'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' || (err as { name?: string }).name === 'RepairCompletedError' || (err as { name?: string }).name === 'RepairLineItemNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// DELETE /repairs/:id/items/:itemId — Delete a line item
// ---------------------------------------------------------------------------

repairsRoutes.delete('/:id/items/:itemId', async (c) => {
  const id = c.req.param('id')
  const itemId = c.req.param('itemId')

  try {
    const deleted = await deleteRepairLineItem(id, itemId)
    return c.json(deleted)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to delete line item'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' || (err as { name?: string }).name === 'RepairCompletedError' || (err as { name?: string }).name === 'RepairLineItemNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/assign — Reassign worker to repair
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/assign', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const result = await assignWorkerToRepair(id, input)
    return c.json(result as RepairDetail)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to assign worker'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// POST /repairs/:id/timer/start — Start a manual work timer session
//
// Creates a new work log entry with startedAt = now and endedAt = null.
// Multiple sessions can be open simultaneously on the same repair.
// ---------------------------------------------------------------------------

repairsRoutes.post('/:id/timer/start', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    // Validate that userId is provided
    if (!input?.userId) {
      return c.json({ error: 'userId is required', code: 'VALIDATION_ERROR' }, 400)
    }

    const result = await startWorkTimer(id, input.userId)
    return c.json(result, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to start timer'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// POST /repairs/:id/timer/stop — Stop an active work timer session
//
// Sets endedAt on the specified work log entry. If already stopped, updates
// endedAt again (extending the recorded duration).
// ---------------------------------------------------------------------------

repairsRoutes.post('/:id/timer/stop', async (c) => {
  const input = await c.req.json()

  try {
    // Validate that workLogId is provided
    if (!input?.workLogId) {
      return c.json({ error: 'workLogId is required', code: 'VALIDATION_ERROR' }, 400)
    }

    const result = await stopWorkTimer(input.workLogId)
    return c.json(result)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to stop timer'
    const status = (err as { name?: string }).name === 'WorkLogNotFoundError' || (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// POST /repairs/:id/complete — Complete repair with payment (atomic transaction)
//
// Accepts single or split payment methods. Atomically:
//   1. Validates repair is in 'ready' status
//   2. Computes total from line items and validates payment amounts match
//   3. Checks stock availability for all parts used
//   4. Creates linked Sale (sourceType='repair') with sale + line items
//   5. Creates payment records and allocations
//   6. Deducts stock via movements (reason='repair_use')
//   7. Marks repair as completed with completedAt timestamp
// All-or-nothing: any failure rolls back everything.
// ---------------------------------------------------------------------------

repairsRoutes.post('/:id/complete', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    // Validate that payments array is provided and non-empty
    if (!input?.payments || !Array.isArray(input.payments) || input.payments.length === 0) {
      return c.json({ error: 'At least one payment method is required', code: 'VALIDATION_ERROR' }, 400)
    }

    // Validate each payment has method and positive amount
    for (const pay of input.payments) {
      if (!pay.method || !['cash', 'card'].includes(pay.method)) {
        return c.json({ error: `Invalid payment method: ${pay?.method}`, code: 'VALIDATION_ERROR' }, 400)
      }
      if (typeof pay.amount !== 'number' || pay.amount <= 0) {
        return c.json({ error: 'Payment amount must be a positive number', code: 'VALIDATION_ERROR' }, 400)
      }
    }

    const result = await completeRepairPayment(id, { payments: input.payments })
    return c.json(result, 200)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Payment completion failed'
    const name = (err as { name?: string }).name || ''

    // Map specific errors to appropriate HTTP status codes
    if (name === 'RepairNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }
    if (name === 'RepairNotReadyError') {
      return c.json({ error: message, code: 'INVALID_STATUS' }, 409)
    }
    if (name === 'PaymentMismatchError') {
      return c.json({ error: message, code: 'PAYMENT_MISMATCH' }, 422)
    }
    if (name === 'InsufficientStockForRepairError') {
      const shortfalls = (err as { shortfalls?: unknown[] }).shortfalls
      return c.json(
        { error: message, code: 'INSUFFICIENT_STOCK', shortfalls },
        422
      )
    }

    return c.json({ error: message, code: name || 'INTERNAL_ERROR' }, 500)
  }
})

