const quotesRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /quotes — List quotes with optional status filter
// ---------------------------------------------------------------------------

quotesRoutes.get('/', async (c) => {
  const statusFilter = c.req.query('status') as string | undefined

  try {
    const result = await getQuotesList(statusFilter)
    return c.json(result)
  } catch (err) {
    console.error('[GET /quotes] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// GET /quotes/:id — Get quote detail with line items
// ---------------------------------------------------------------------------

quotesRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    const quote = await getQuoteById(id)
    return c.json(quote as QuoteDetail)
  } catch (err) {
    if (err instanceof Error && err.name === 'QuoteNotFoundError') {
      return c.json({ error: 'Quote not found', code: 'NOT_FOUND' }, 404)
    }

    console.error('[GET /quotes/:id] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// POST /quotes — Create a new draft quote
// ---------------------------------------------------------------------------

quotesRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    // Validate required fields
    if (!input || typeof input !== 'object') {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const quote = await createQuote({
      customerId: input.customerId ?? null,
      notes: input.notes ?? null,
    })

    return c.json(quote as QuoteDetail, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to create quote'
    console.error('[POST /quotes] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

