// ---------------------------------------------------------------------------
// Helper — Get VAT rate for a given vatRateId
// ---------------------------------------------------------------------------

async function getVatRate(vatRateId: string): Promise<{ rate: number }> {
  const [rate] = await db.select({ rate: vatRates.rate }).from(vatRates).where(eq(vatRates.id, vatRateId))
  if (!rate) {
    throw new Error(`VAT rate not found: ${vatRateId}`)
  }
  return rate
}

// ---------------------------------------------------------------------------
// Helper — Generate quote number from sequence
// ---------------------------------------------------------------------------

async function generateQuoteNumber(): Promise<string> {
  const updateResult = await db
    .update(sequences)
    .set({ currentValue: sql`${sequences.currentValue} + 1` })
    .where(eq(sequences.name, 'quote'))

  if (updateResult.changes === 0) {
    // Sequence doesn't exist yet — create it starting at 1
    await db.insert(sequences).values({ name: 'quote', currentValue: 1 })
  }

  const [seqRow] = await db
    .select({ currentValue: sequences.currentValue })
    .from(sequences)
    .where(eq(sequences.name, 'quote'))

  const seqNum = seqRow!.currentValue
  return `QT-${String(seqNum).padStart(4, '0')}`
}

// ---------------------------------------------------------------------------
// Helper — Enforce draft-only access on a quote
// ---------------------------------------------------------------------------

async function enforceDraftStatus(quoteId: string): Promise<void> {
  const [quote] = await db.select({ status: quotes.status }).from(quotes).where(eq(quotes.id, quoteId))

  if (!quote) {
    throw new QuoteNotFoundError(quoteId)
  }

  if (quote.status !== 'draft') {
    throw new QuoteNotDraftError(quoteId, quote.status as string)
  }
}

// ---------------------------------------------------------------------------
// Service Functions — Quote CRUD
// ---------------------------------------------------------------------------

/**
 * Create a new draft quote with auto-generated quote number.
 */
export async function createQuote(input: {
  customerId?: string | null
  notes?: string | null
}): Promise<QuoteDetail> {
  const quoteNumber = await generateQuoteNumber()
  const now = Date.now()

  const [inserted] = await db
    .insert(quotes)
    .values({
      id: crypto.randomUUID(),
      quoteNumber,
      customerId: input.customerId ?? null,
      status: 'draft',
      notes: input.notes ?? null,
      createdAt: new Date(now),
      updatedAt: new Date(now),
    })
    .returning()

  return getQuoteDetail(inserted.id)
}

/**
 * List quotes with optional status filter. Returns newest first.
 */
export async function getQuotesList(statusFilter?: string): Promise<QuoteListResult> {
  const typedStatus = statusFilter as 'draft' | 'sent' | 'converted' | 'rejected'
  const whereClause = statusFilter ? eq(quotes.status, typedStatus) : undefined

  const quoteRows = await db
    .select({
      id: quotes.id,
      quoteNumber: quotes.quoteNumber,
      customerId: quotes.customerId,
      status: quotes.status,
      notes: quotes.notes,
      createdAt: quotes.createdAt,
      updatedAt: quotes.updatedAt,
    })
    .from(quotes)
    .where(whereClause)
    .orderBy(desc(quotes.createdAt))

  const total = quoteRows.length

  return {
    quotes: quoteRows.map(row => ({
      ...row,
      createdAt: row.createdAt.getTime(),
      updatedAt: row.updatedAt.getTime(),
    })),
    total,
  }
}

/**
 * Get a single quote by ID with its line items.
 */
export async function getQuoteById(quoteId: string): Promise<QuoteDetail> {
  const [quote] = await db.select().from(quotes).where(eq(quotes.id, quoteId))

  if (!quote) {
    throw new QuoteNotFoundError(quoteId)
  }

  return getQuoteDetail(quoteId)
}

/**
 * Update draft-only fields on a quote (customerId, notes).
 */
export async function updateQuote(quoteId: string, input: {
  customerId?: string | null
  notes?: string | null
}): Promise<QuoteDetail> {
  // Enforce draft status before allowing updates
  await enforceDraftStatus(quoteId)

  const now = Date.now()
  await db
    .update(quotes)
    .set({
      ...(input.customerId !== undefined && { customerId: input.customerId }),
      ...(input.notes !== undefined && { notes: input.notes }),
      updatedAt: new Date(now),
    })
    .where(eq(quotes.id, quoteId))

  return getQuoteDetail(quoteId)
}

/**
 * Delete a draft quote and all its line items.
 */
export async function deleteQuote(quoteId: string): Promise<void> {
  // Enforce draft status before allowing deletion
  await enforceDraftStatus(quoteId)

  // Delete line items first (foreign key constraint)
  await db.delete(quoteLineItems).where(eq(quoteLineItems.quoteId, quoteId))

  // Delete the quote
  await db.delete(quotes).where(eq(quotes.id, quoteId))
}

// ---------------------------------------------------------------------------
// Service Functions — Quote Line Item CRUD
// ---------------------------------------------------------------------------

/**
 * Create a new line item for a quote. Validates draft status and calculates totals.
 */
export async function createQuoteLineItem(quoteId: string, input: {
  lineType: 'part' | 'labor' | 'bicycle'
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent?: number | null
  partId?: string | null
  laborServiceId?: string | null
  // Bicycle fields (only for lineType === 'bicycle')
  bicycleId?: string | null
  bicycleBrand?: string | null
  bicycleModel?: string | null
  bicycleYear?: number | null
  bicycleColor?: string | null
  bicycleFrameSize?: string | null
}): Promise<QuoteLineItem> {
  // Enforce draft status on parent quote
  await enforceDraftStatus(quoteId)

  const now = Date.now()

  // Fetch VAT rate to calculate tax amounts
  const vatRate = await getVatRate(input.vatRateId)

  // Calculate line totals (discount in basis points: 100 = 1%, 10000 = 100%)
  const discountMultiplier = input.discountPercent != null ? 1 - input.discountPercent / 10000 : 1
  const lineTotalNet = Math.round(input.unitPriceNet * input.quantity * discountMultiplier)
  const lineTotalVat = Math.round(lineTotalNet * vatRate.rate / 10000)
  const lineTotalGross = lineTotalNet + lineTotalVat

  const lineItemId = crypto.randomUUID()

  // Use raw SQL for insert to avoid Drizzle ORM issues with spread columns
  const client = sqliteDb as Database.Database

  client.prepare(
    'INSERT INTO quote_line_items (id, quote_id, line_type, part_id, labor_service_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, bicycle_id, bicycle_brand, bicycle_model, bicycle_year, bicycle_color, bicycle_frame_size, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
  ).run(
    lineItemId,
    quoteId,
    input.lineType,
    input.partId ?? null,
    input.laborServiceId ?? null,
    input.description,
    input.quantity,
    input.unitPriceNet,
    input.vatRateId,
    input.discountPercent !== undefined ? input.discountPercent : null,
    lineTotalNet,
    lineTotalVat,
    lineTotalGross,
    input.bicycleId ?? null,
    input.bicycleBrand ?? null,
    input.bicycleModel ?? null,
    input.bicycleYear ?? null,
    input.bicycleColor ?? null,
    input.bicycleFrameSize ?? null,
    now
  )

  const [inserted] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))

  return {
    ...inserted,
    createdAt: inserted.createdAt.getTime(),
  } as QuoteLineItem
}

/**
 * Update an existing line item. Validates draft status on parent quote.
 */
export async function updateQuoteLineItem(quoteId: string, lineItemId: string, input: {
  description?: string
  quantity?: number
  unitPriceNet?: number
  vatRateId?: string
  discountPercent?: number | null
  partId?: string | null
  laborServiceId?: string | null
  // Bicycle fields (only for lineType === 'bicycle')
  bicycleId?: string | null
  bicycleBrand?: string | null
  bicycleModel?: string | null
  bicycleYear?: number | null
  bicycleColor?: string | null
  bicycleFrameSize?: string | null
}): Promise<QuoteLineItem> {
  // Enforce draft status on parent quote
  await enforceDraftStatus(quoteId)

  // Fetch existing line item to get its type and current values for recalculation
  const [existing] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))

  if (!existing) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  // Verify the line item belongs to this quote
  if (existing.quoteId !== quoteId) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  // Determine effective values for recalculation (used when fields aren't being updated)
  const effUnitPriceNet = input.unitPriceNet ?? existing.unitPriceNet
  const effQuantity = input.quantity ?? existing.quantity
  const effDiscountPercent = input.discountPercent !== undefined ? (input.discountPercent != null ? input.discountPercent : null) : existing.discountPercent
  const effVatRateId = input.vatRateId ?? existing.vatRateId

  // Fetch VAT rate for recalculation
  const vatRate = await getVatRate(effVatRateId)

  // Recalculate totals based on effective values
  const discountMultiplier = effDiscountPercent != null ? 1 - effDiscountPercent / 10000 : 1
  const lineTotalNet = Math.round(effUnitPriceNet * effQuantity * discountMultiplier)
  const lineTotalVat = Math.round(lineTotalNet * vatRate.rate / 10000)
  const lineTotalGross = lineTotalNet + lineTotalVat

  // Build dynamic SQL with only the fields that were provided
  const setClauses: string[] = []
  const params: unknown[] = []

  if (input.description !== undefined) {
    setClauses.push('description = ?')
    params.push(input.description)
  }
  if (input.quantity !== undefined) {
    setClauses.push('quantity = ?')
    params.push(input.quantity)
  }
  if (input.unitPriceNet !== undefined) {
    setClauses.push('unit_price_net = ?')
    params.push(input.unitPriceNet)
  }
  if (input.vatRateId !== undefined) {
    setClauses.push('vat_rate_id = ?')
    params.push(input.vatRateId)
  }
  if (input.discountPercent !== undefined) {
    setClauses.push('discount_percent = ?')
    params.push(input.discountPercent != null ? input.discountPercent : null)
  }

  // Always update totals (no updated_at column on quote_line_items)
  setClauses.push('line_total_net = ?', 'line_total_vat = ?', 'line_total_gross = ?')
  params.push(lineTotalNet, lineTotalVat, lineTotalGross)

  // Type-specific fields (always update if provided)
  if (input.partId !== undefined) {
    setClauses.push('part_id = ?')
    params.push(input.partId ?? null)
  }
  if (input.laborServiceId !== undefined) {
    setClauses.push('labor_service_id = ?')
    params.push(input.laborServiceId ?? null)
  }
  if (input.bicycleId !== undefined) {
    setClauses.push('bicycle_id = ?')
    params.push(input.bicycleId ?? null)
  }
  if (input.bicycleBrand !== undefined) {
    setClauses.push('bicycle_brand = ?')
    params.push(input.bicycleBrand ?? null)
  }
  if (input.bicycleModel !== undefined) {
    setClauses.push('bicycle_model = ?')
    params.push(input.bicycleModel ?? null)
  }
  if (input.bicycleYear !== undefined) {
    setClauses.push('bicycle_year = ?')
    params.push(input.bicycleYear ?? null)
  }
  if (input.bicycleColor !== undefined) {
    setClauses.push('bicycle_color = ?')
    params.push(input.bicycleColor ?? null)
  }
  if (input.bicycleFrameSize !== undefined) {
    setClauses.push('bicycle_frame_size = ?')
    params.push(input.bicycleFrameSize ?? null)
  }

  // Use raw SQL for update to avoid Drizzle ORM issues with spread columns
  const client = sqliteDb as Database.Database

  if (setClauses.length === 0) {
    // No fields to update — just return the existing item
    const [existingItem] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))
    return { ...existingItem, createdAt: existingItem.createdAt.getTime() } as QuoteLineItem
  }

  client.prepare(
    `UPDATE quote_line_items SET ${setClauses.join(', ')} WHERE id = ?`
  ).run(...params, lineItemId)

  const [updated] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))

  return {
    ...updated,
    createdAt: updated.createdAt.getTime(),
  } as QuoteLineItem
}

/**
 * Delete a line item. Validates draft status on parent quote.
 */
export async function deleteQuoteLineItem(quoteId: string, lineItemId: string): Promise<void> {
  // Enforce draft status on parent quote
  await enforceDraftStatus(quoteId)

  const [existing] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))

  if (!existing) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  // Verify the line item belongs to this quote
  if (existing.quoteId !== quoteId) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  await db.delete(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))
}

// ---------------------------------------------------------------------------
// Helper — Build full quote detail with line items
// ---------------------------------------------------------------------------

async function getQuoteDetail(quoteId: string): Promise<QuoteDetail> {
  const [quote] = await db.select().from(quotes).where(eq(quotes.id, quoteId))

  if (!quote) {
    throw new QuoteNotFoundError(quoteId)
  }

  const lineItemsRows = await db
    .select()
    .from(quoteLineItems)
    .where(eq(quoteLineItems.quoteId, quoteId))
    .orderBy(asc(quoteLineItems.id))

  return {
    id: quote.id,
    quoteNumber: quote.quoteNumber,
    customerId: quote.customerId,
    status: quote.status as QuoteStatus,
    notes: quote.notes,
    lineItems: lineItemsRows.map(row => ({
      ...row,
      createdAt: row.createdAt.getTime(),
    })) as QuoteLineItem[],
    createdAt: quote.createdAt.getTime(),
    updatedAt: quote.updatedAt.getTime(),
  }
}

