import { useState, useEffect, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import { Plus, Filter, Eye } from 'lucide-react'
import {
  QUOTE_STATUS_COLORS,
  type QuoteStatus,
  type QuoteListItem,
} from '../types.js'
import { getQuotes, type QuotesListResponse } from '../api.js'



// ---------------------------------------------------------------------------
// Component — Status Badge
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: QuoteStatus }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${QUOTE_STATUS_COLORS[status]}`}>
      {status}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Component — Customer Name Helper
// ---------------------------------------------------------------------------

function getCustomerName(customerId: string | null): string {
  if (!customerId) return '—'
  // In production, this would fetch customer details from the API.
  // For now, show a truncated ID as placeholder.
  return `Customer ${customerId.slice(0, 8)}...`
}

// ---------------------------------------------------------------------------
// Component — Date Formatter
// ---------------------------------------------------------------------------

function formatDate(epochMs: number): string {
  const d = new Date(epochMs)
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
}

// ---------------------------------------------------------------------------
// Component — Quotes Page
// ---------------------------------------------------------------------------

export function QuotesPage() {
  const navigate = useNavigate()
  const [quotes, setQuotes] = useState<QuoteListItem[]>([])
  const [totalPages, setTotalPages] = useState(1)
  const [currentPage, setCurrentPage] = useState(1)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [statusFilter, setStatusFilter] = useState<QuoteStatus | ''>('')

  // Fetch quotes list
  const fetchQuotes = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const data: QuotesListResponse = await getQuotes(statusFilter || undefined)
      setQuotes(data.quotes)
      setTotalPages(Math.ceil(data.total / 20))
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load quotes')
    } finally {
      setLoading(false)
    }
  }, [statusFilter])

  useEffect(() => {
    fetchQuotes()
  }, [fetchQuotes, currentPage])

  // Handle "New Quote" button click
  const handleNewQuote = () => {
    navigate('/quotes/new')
  }

  // Handle row click to view detail
  const handleViewQuote = (id: string) => {
    navigate(`/quotes/${id}`)
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-gray-900">Quotes</h1>
        <button
          onClick={handleNewQuote}
          className="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white shadow-sm hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
        >
          <Plus className="h-4 w-4" />
          New Quote
        </button>
      </div>

      {/* Filters */}
      <div className="flex items-center gap-3">
        <Filter className="h-4 w-4 text-gray-400" />
        <select
          value={statusFilter}
          onChange={(e) => {
            setStatusFilter(e.target.value as QuoteStatus | '')
            setCurrentPage(1)
          }}
          className="rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
        >
          <option value="">All Statuses</option>
          <option value="draft">Draft</option>
          <option value="sent">Sent</option>
          <option value="converted">Converted</option>
          <option value="rejected">Rejected</option>
        </select>
      </div>

      {/* Error State */}
      {error && (
        <div className="rounded-lg bg-red-50 p-4 text-sm text-red-700">
          {error}
        </div>
      )}

      {/* Loading State */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <div className="h-6 w-6 animate-spin rounded-full border-2 border-blue-600 border-t-transparent" />
        </div>
      ) : quotes.length === 0 ? (
        /* Empty State */
        <div className="rounded-lg border border-dashed border-gray-300 p-12 text-center">
          <p className="text-sm text-gray-500">No quotes found</p>
          <button
            onClick={handleNewQuote}
            className="mt-3 inline-flex items-center gap-2 text-sm font-medium text-blue-600 hover:text-blue-700"
          >
            <Plus className="h-4 w-4" />
            Create your first quote
          </button>
        </div>
      ) : (
        /* Quotes Table */
        <div className="overflow-hidden rounded-lg border border-gray-200 bg-white shadow-sm">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Quote #</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Status</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Customer</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Created</th>
                <th className="px-4 py-3 text-right text-xs font-medium uppercase tracking-wide text-gray-500">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {quotes.map((quote) => (
                <tr key={quote.id} className="hover:bg-gray-50">
                  <td className="whitespace-nowrap px-4 py-3 text-sm font-medium text-gray-900">
                    {quote.quoteNumber}
