          <div className="flex gap-2">
            <button
              onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
              disabled={currentPage === 1}
              className="rounded-md border border-gray-300 px-3 py-1.5 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
            >
              Previous
            </button>
            <button
              onClick={() => setCurrentPage(Math.min(totalPages, currentPage + 1))}
              disabled={currentPage === totalPages}
              className="rounded-md border border-gray-300 px-3 py-1.5 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
            >
              Next
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

/**
 * Create Quote Form — Dialog for creating a new draft quote.
 */

import { useState, useEffect } from 'react'
import { X, User, Building2 } from 'lucide-react'
import type { CreateQuoteFormData } from '../types.js'
import { createEmptyQuoteForm } from '../types.js'
import { createQuote } from '../api.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface QuoteCustomer {
  id: string
  displayName: string
  type: 'private' | 'company'
}

interface CreateQuoteDialogProps {
  isOpen: boolean
  onClose: () => void
  onSuccess: (quoteId: string) => void
}

// ---------------------------------------------------------------------------
// Component — Customer Selector
// ---------------------------------------------------------------------------

function CustomerSelector({
  selectedCustomerId,
  onSelect,
}: {
  selectedCustomerId: string | null
  onSelect: (customerId: string | null) => void
}) {
  const [customers, setCustomers] = useState<QuoteCustomer[]>([])
  const [searchTerm, setSearchTerm] = useState('')
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    async function fetchCustomers() {
      setLoading(true)
      try {
        // Fetch customers from API with optional search filter
        const params = new URLSearchParams({ limit: '50' })
        if (searchTerm) params.set('search', searchTerm)

        const response = await fetch(`/api/customers?${params.toString()}`)
        if (!response.ok) throw new Error('Failed to fetch customers')

        const data = await response.json() as { items: QuoteCustomer[]; total: number }
        setCustomers(data.items ?? [])
      } catch (err) {
        console.error('[CreateQuoteForm] Failed to load customers:', err)
        setCustomers([])
      } finally {
        setLoading(false)
      }
    }

    fetchCustomers()
  }, [searchTerm]) // Re-fetch when search term changes

  return (
    <div className="space-y-2">
      <label className="block text-sm font-medium text-gray-700">Customer</label>

      {/* Search */}
      <input
        type="text"
        placeholder="Search customers..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
      />

      {/* Customer List */}
      {loading ? (
        <div className="flex items-center justify-center py-4">
          <div className="h-4 w-4 animate-spin rounded-full border-2 border-blue-600 border-t-transparent" />
        </div>
      ) : customers.length === 0 && searchTerm ? (
        <p className="py-2 text-sm text-gray-500">No customers found</p>
      ) : (
        <div className="max-h-48 overflow-y-auto rounded-lg border border-gray-200">
          {customers.map((customer) => (
            <button
              key={customer.id}
              onClick={() => {
                onSelect(customer.id)
                setSearchTerm('')
              }}
              className={`flex w-full items-center gap-3 px-3 py-2 text-left text-sm hover:bg-gray-50 ${
                selectedCustomerId === customer.id ? 'bg-blue-50' : ''
              }`}
            >
              {customer.type === 'company' ? (
                <Building2 className="h-4 w-4 flex-shrink-0 text-gray-400" />
              ) : (
                <User className="h-4 w-4 flex-shrink-0 text-gray-400" />
              )}
              <div className="min-w-0">
                <p className="truncate font-medium text-gray-900">{customer.displayName}</p>
                <p className="text-xs text-gray-500 capitalize">{customer.type}</p>
              </div>
            </button>
          ))}

          {/* Clear selection */}
          {selectedCustomerId && (
            <button
              onClick={() => onSelect(null)}
              className="flex w-full items-center gap-3 px-3 py-2 text-left text-sm font-medium text-red-600 hover:bg-red-50"
            >
              <X className="h-4 w-4 flex-shrink-0" />
              None (walk-in)
            </button>
          )}
        </div>
      )}

      {selectedCustomerId && (
        <p className="text-xs text-gray-500">Selected customer will be linked to this quote</p>
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Component — Create Quote Dialog
// ---------------------------------------------------------------------------

export function CreateQuoteDialog({ isOpen, onClose, onSuccess }: CreateQuoteDialogProps) {
  const [formData, setFormData] = useState<CreateQuoteFormData>(createEmptyQuoteForm())
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Reset form when dialog opens
  useEffect(() => {
    if (isOpen) {
      setFormData(createEmptyQuoteForm())
      setError(null)
    }
  }, [isOpen])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)

    try {
      const quote = await createQuote(formData)
      onSuccess(quote.id)
      onClose()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create quote')
    } finally {
      setSubmitting(false)
    }
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />

      {/* Dialog */}
      <div className="relative w-full max-w-lg rounded-xl bg-white p-6 shadow-xl">
        {/* Header */}
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-semibold text-gray-900">New Quote</h2>
          <button
            onClick={onClose}
            className="rounded-md p-1 text-gray-400 hover:bg-gray-100 hover:text-gray-600"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-4">
          {error && (
            <div className="rounded-lg bg-red-50 p-3 text-sm text-red-700">{error}</div>
          )}

          <CustomerSelector
            selectedCustomerId={formData.customerId}
            onSelect={(customerId) => setFormData(prev => ({ ...prev, customerId }))}
          />

          {/* Notes */}
          <div className="space-y-2">
            <label htmlFor="notes" className="block text-sm font-medium text-gray-700">
              Notes (optional)
            </label>
            <textarea
              id="notes"
              rows={3}
              value={formData.notes}
              onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
              placeholder="Internal notes about this quote..."
              className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 resize-none"
            />
          </div>

          {/* Total Discount */}
          <div className="space-y-2">
            <label htmlFor="totalDiscount" className="block text-sm font-medium text-gray-700">
              Total Discount (%) — client-side only
            </label>
            <input
              id="totalDiscount"
              type="number"
              min={0}
              max={100}
              step={0.1}
              value={formData.totalDiscountPercent ?? ''}
              onChange={(e) => {
                const val = e.target.value === '' ? null : parseFloat(e.target.value)
                setFormData(prev => ({ ...prev, totalDiscountPercent: val }))
              }}
              placeholder="0"
              className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
            />
            <p className="text-xs text-gray-500">Applied client-side to line item totals. Not persisted to database.</p>
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              disabled={submitting}
              className="rounded-lg border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {submitting ? 'Creating...' : 'Create Quote'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

/**
 * Quote Detail Panel — Shows quote header + editable line items table.
 */

import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  ArrowLeft,
  Plus,
  Trash2,
  X,
  AlertTriangle,
  Pencil,
} from 'lucide-react'
import {
  QUOTE_STATUS_COLORS,
  LINE_TYPE_LABELS,
  type QuoteDetail,
  type QuoteLineItem,
} from '../types.js'
import { getQuote, deleteQuote, createQuoteLineItem, updateQuoteLineItem, deleteQuoteLineItem } from '../api.js'
import { formatCentsToEuro } from '@/shared/lib/utils.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface QuoteDetailPanelProps {
  quoteId: string
}

// ---------------------------------------------------------------------------
// Component — Status Badge
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: string }) {
  const colorClass = QUOTE_STATUS_COLORS[status as keyof typeof QUOTE_STATUS_COLORS] || 'bg-gray-100 text-gray-800'
  return (
    <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${colorClass}`}>
      {status}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Component — Stock Warning Indicator
// ---------------------------------------------------------------------------

function StockWarning({ partId }: { partId: string | null }) {
  if (!partId) return null

  // In production, this would check stock levels from the API.
  // For now, we show a placeholder warning for demonstration.
  return (
    <span className="inline-flex items-center gap-1 text-xs text-orange-600">
      <AlertTriangle className="h-3 w-3" />
      Low stock
    </span>
  )
}

// ---------------------------------------------------------------------------
// Component — Line Item Editor Row
// ---------------------------------------------------------------------------

function LineItemRow({
  item,
  onDelete,
}: {
  item: QuoteLineItem
  onDelete: () => void
}) {
  const [editing, setEditing] = useState(false)
  const [editData, setEditData] = useState({
    description: item.description,
    quantity: item.quantity.toString(),
    unitPriceNet: item.unitPriceNet.toString(),
    discountPercent: item.discountPercent?.toString() ?? '',
  })

  const handleSave = async () => {
    try {
      await updateQuoteLineItem(item.quoteId, item.id, {
        lineType: item.lineType,
        description: editData.description,
        quantity: parseInt(editData.quantity, 10) || 1,
        unitPriceNet: parseInt(editData.unitPriceNet, 10) || 0,
        vatRateId: item.vatRateId,
        discountPercent: editData.discountPercent ? parseInt(editData.discountPercent, 10) : null,
      })
      setEditing(false)
    } catch (err) {
      console.error('[QuoteDetailPanel] Failed to update line item:', err)
    }
  }

  const handleDelete = async () => {
    if (window.confirm('Delete this line item?')) {
      try {
        await deleteQuoteLineItem(item.quoteId, item.id)
        onDelete()
      } catch (err) {
        console.error('[QuoteDetailPanel] Failed to delete line item:', err)
      }
    }
  }

  return (
    <tr className={`${editing ? 'bg-yellow-50' : ''}`}>
      {/* Type */}
      <td className="whitespace-nowrap px-3 py-2 text-xs font-medium text-gray-500">
        {LINE_TYPE_LABELS[item.lineType]}
      </td>

      {/* Description */}
      <td className="px-3 py-2">
        {editing ? (
          <input
            type="text"
            value={editData.description}
            onChange={(e) => setEditData(prev => ({ ...prev, description: e.target.value }))}
            className="w-full rounded border border-gray-300 px-2 py-1 text-sm focus:border-blue-500 focus:outline-none"
          />
        ) : (
          <div>
            <span className="text-sm text-gray-900">{item.description}</span>
            {item.lineType === 'part' && item.partId && (
              <div className="mt-0.5">
                <StockWarning partId={item.partId} />
              </div>
            )}
          </div>
        )}
      </td>

      {/* Quantity */}
      <td className="whitespace-nowrap px-3 py-2 text-sm text-gray-700">
        {editing ? (
          <input
            type="number"
            min={1}
            value={editData.quantity}
            onChange={(e) => setEditData(prev => ({ ...prev, quantity: e.target.value }))}
            className="w-16 rounded border border-gray-300 px-2 py-1 text-sm focus:border-blue-500 focus:outline-none"
          />
        ) : (
          item.quantity
        )}
      </td>

      {/* Unit Price */}
      <td className="whitespace-nowrap px-3 py-2 text-right text-sm text-gray-700">
        {formatCentsToEuro(item.unitPriceNet)}
      </td>

      {/* Discount */}
      <td className="whitespace-nowrap px-3 py-2 text-right text-sm text-gray-500">
        {item.discountPercent !== null ? `${(item.discountPercent / 100).toFixed(1)}%` : '—'}
      </td>

      {/* Line Total */}
      <td className="whitespace-nowrap px-3 py-2 text-right text-sm font-medium text-gray-900">
        {formatCentsToEuro(item.lineTotalGross)}
      </td>

      {/* Actions */}
      <td className="whitespace-nowrap px-3 py-2 text-right">
        {editing ? (
          <div className="flex justify-end gap-1">
            <button
              onClick={handleSave}
              className="rounded-md p-1 text-green-600 hover:bg-green-50"
              title="Save"
            >
              <Pencil className="h-4 w-4" />
            </button>
            <button
              onClick={() => setEditing(false)}
              className="rounded-md p-1 text-gray-400 hover:bg-gray-100"
              title="Cancel"
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        ) : (
          <div className="flex justify-end gap-1">
            <button
              onClick={() => setEditing(true)}
              className="rounded-md p-1 text-blue-600 hover:bg-blue-50"
              title="Edit"
            >
              <Pencil className="h-4 w-4" />
            </button>
            <button
              onClick={handleDelete}
              className="rounded-md p-1 text-red-600 hover:bg-red-50"
              title="Delete"
            >
              <Trash2 className="h-4 w-4" />
            </button>
          </div>
        )}
      </td>
    </tr>
  )
}

// ---------------------------------------------------------------------------
// Component — Quote Detail Panel
// ---------------------------------------------------------------------------

export function QuoteDetailPanel({ quoteId }: QuoteDetailPanelProps) {
  const navigate = useNavigate()
  const [quote, setQuote] = useState<QuoteDetail | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showAddLineItem, setShowAddLineItem] = useState(false)
  // Total discount — client-side only (not persisted to DB)
  const [totalDiscountPercent, setTotalDiscountPercent] = useState<number | null>(null)

  // Fetch quote detail
  useEffect(() => {
    async function fetchQuote() {
      try {
        const data = await getQuote(quoteId)
        setQuote(data)
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load quote')
      } finally {
        setLoading(false)
      }
    }

    fetchQuote()
  }, [quoteId])

  // Handle line item refresh after add/update/delete
  const handleLineItemChange = async () => {
    try {
      const updated = await getQuote(quoteId)
      setQuote(updated)
    } catch (err) {
      console.error('[QuoteDetailPanel] Failed to refresh quote:', err)
    }
  }

  // Handle deleting the quote
  const handleDeleteQuote = async () => {
    if (!quote || quote.status !== 'draft') return
    if (window.confirm('Are you sure you want to delete this quote? This cannot be undone.')) {
      try {
        await deleteQuote(quoteId)
        navigate('/quotes')
      } catch (err) {
        console.error('[QuoteDetailPanel] Failed to delete quote:', err)
      }
    }
  }

  // Calculate totals with optional client-side discount
  const subtotalNet = quote?.lineItems.reduce((sum, item) => sum + item.lineTotalNet, 0) ?? 0
  const subtotalVat = quote?.lineItems.reduce((sum, item) => sum + item.lineTotalVat, 0) ?? 0

  // Apply total discount (client-side only)
  const discountMultiplier = totalDiscountPercent != null ? 1 - totalDiscountPercent / 100 : 1
  const totalNet = Math.round(subtotalNet * discountMultiplier)
  const totalVat = Math.round(subtotalVat * discountMultiplier)
  const totalGross = totalNet + totalVat

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="h-6 w-6 animate-spin rounded-full border-2 border-blue-600 border-t-transparent" />
      </div>
    )
  }

  if (error || !quote) {
    return (
      <div className="space-y-4">
        <button
          onClick={() => navigate('/quotes')}
          className="inline-flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to Quotes
        </button>
        <div className="rounded-lg bg-red-50 p-4 text-sm text-red-700">
          {error || 'Quote not found'}
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <button
          onClick={() => navigate('/quotes')}
          className="inline-flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to Quotes
        </button>

        {quote.status === 'draft' && (
          <button
            onClick={handleDeleteQuote}
            className="inline-flex items-center gap-1 rounded-md px-3 py-1.5 text-sm font-medium text-red-600 hover:bg-red-50"
          >
            <Trash2 className="h-4 w-4" />
            Delete Quote
          </button>
        )}
      </div>

      {/* Quote Header Card */}
      <div className="rounded-lg border border-gray-200 bg-white p-6 shadow-sm">
        <div className="flex items-start justify-between">
          <div>
            <h1 className="text-xl font-bold text-gray-900">{quote.quoteNumber}</h1>
            <p className="mt-1 text-sm text-gray-500">
              Created {new Date(quote.createdAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' })}
            </p>
          </div>
          <StatusBadge status={quote.status} />
        </div>

        {/* Notes */}
        {quote.notes && (
          <div className="mt-4 rounded-lg bg-gray-50 p-3">
            <p className="text-sm text-gray-700 whitespace-pre-wrap">{quote.notes}</p>
          </div>
        )}

        {/* Customer */}
        {quote.customerId && (
          <div className="mt-4 flex items-center gap-2 text-sm text-gray-600">
            <span className="font-medium">Customer:</span>
            <span>{`Customer ${quote.customerId.slice(0, 8)}...`}</span>
          </div>
        )}
      </div>

      {/* Line Items Section */}
      <div className="rounded-lg border border-gray-200 bg-white shadow-sm">
        {/* Section Header */}
        <div className="flex items-center justify-between border-b border-gray-200 px-6 py-4">
          <h2 className="text-base font-semibold text-gray-900">Line Items</h2>
          {quote.status === 'draft' && (
            <div className="flex items-center gap-3">
              {/* Total Discount Control */}
              <div className="flex items-center gap-1.5">
                <label htmlFor="totalDiscountPanel" className="text-xs text-gray-600">Total disc.:</label>
                <input
                  id="totalDiscountPanel"
                  type="number"
                  min={0}
                  max={100}
                  step={0.1}
                  value={totalDiscountPercent ?? ''}
                  onChange={(e) => {
                    const val = e.target.value === '' ? null : parseFloat(e.target.value)
                    setTotalDiscountPercent(val)
                  }}
                  placeholder="0%"
                  className="w-16 rounded border border-gray-300 px-2 py-1 text-xs focus:border-blue-500 focus:outline-none"
                />
              </div>
              <button
                onClick={() => setShowAddLineItem(true)}
                className="inline-flex items-center gap-1 rounded-lg bg-blue-600 px-3 py-1.5 text-xs font-medium text-white hover:bg-blue-700"
              >
                <Plus className="h-3 w-3" />
                Add Item
              </button>
            </div>
          )}
        </div>

        {/* Line Items Table */}
        {quote.lineItems.length === 0 ? (
          <div className="p-8 text-center">
            <p className="text-sm text-gray-500">No line items yet</p>
            {quote.status === 'draft' && (
              <button
                onClick={() => setShowAddLineItem(true)}
                className="mt-2 inline-flex items-center gap-1 text-xs font-medium text-blue-600 hover:text-blue-700"
              >
                <Plus className="h-3 w-3" />
                Add your first item
              </button>
            )}
          </div>
        ) : (
          <>
            {/* Table Header */}
            <table className="min-w-full">
              <thead>
                <tr className="border-b border-gray-200 bg-gray-50 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
                  <th className="px-3 py-2 w-24">Type</th>
                  <th className="px-3 py-2">Description</th>
                  <th className="px-3 py-2 w-16 text-center">Qty</th>
                  <th className="px-3 py-2 w-28 text-right">Unit Price</th>
                  <th className="px-3 py-2 w-20 text-right">Discount</th>
                  <th className="px-3 py-2 w-28 text-right">Total</th>
                  <th className="px-3 py-2 w-24 text-right">Actions</th>
                </tr>
              </thead>
              {/* Table Body */}
              <tbody className="divide-y divide-gray-100">
                {quote.lineItems.map((item) => (
                  <LineItemRow
                    key={item.id}
                    item={item}
                    onDelete={() => handleLineItemChange()}
                  />
                ))}
              </tbody>
            </table>

            {/* Totals */}
            <div className="border-t border-gray-200 bg-gray-50 px-6 py-4">
              <div className="space-y-1 text-sm">
                <div className="flex justify-between text-gray-600">
                  <span>Subtotal (net)</span>
                  <span>{formatCentsToEuro(subtotalNet)}</span>
                </div>
                {totalDiscountPercent != null && (
                  <div className="flex justify-between text-green-600">
                    <span>Total discount ({totalDiscountPercent}%)</span>
                    <span>-{formatCentsToEuro(subtotalNet - totalNet)}</span>
                  </div>
                )}
                <div className="flex justify-between text-gray-600">
                  <span>VAT</span>
                  <span>{formatCentsToEuro(totalVat)}</span>
                </div>
                <div className="flex justify-between border-t border-gray-200 pt-1 text-base font-semibold text-gray-900">
                  <span>Total (gross)</span>
                  <span>{formatCentsToEuro(totalGross)}</span>
                </div>
              </div>
            </div>
          </>
        )}
      </div>

      {/* Add Line Item Modal */}
      {showAddLineItem && (
        <AddLineItemModal
          quoteId={quoteId}
          onClose={() => setShowAddLineItem(false)}
          onAdded={() => handleLineItemChange()}
        />
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Component — Add Line Item Modal (inline for simplicity)
// ---------------------------------------------------------------------------

function AddLineItemModal({
  quoteId,
  onClose,
  onAdded,
}: {
  quoteId: string
  onClose: () => void
  onAdded: () => void
}) {
  const [lineType, setLineType] = useState<'part' | 'labor' | 'bicycle'>('part')
  const [description, setDescription] = useState('')
  const [quantity, setQuantity] = useState('1')
  const [unitPriceNet, setUnitPriceNet] = useState('')
  const [vatRateId, setVatRateId] = useState('vat-standard')
  const [discountPercent, setDiscountPercent] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Available VAT rates (hardcoded for now; in production would fetch from API)
  const vatRates = [
    { id: 'vat-standard', rate: 2100, label: 'Standard 21%' },
    { id: 'vat-reduced', rate: 800, label: 'Reduced 8%' },
    { id: 'vat-zero', rate: 0, label: 'Zero 0%' },
  ]

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!description || !unitPriceNet) return

    setSubmitting(true)
    setError(null)

    try {
      const baseData = {
        lineType,
        description,
        quantity: parseInt(quantity, 10) || 1,
        unitPriceNet: parseInt(unitPriceNet, 10),
        vatRateId,
        discountPercent: discountPercent ? parseInt(discountPercent, 10) : null,
      }

      if (lineType === 'part') {
        await createQuoteLineItem(quoteId, { ...baseData, lineType: 'part', partId: null })
      } else if (lineType === 'labor') {
        await createQuoteLineItem(quoteId, { ...baseData, lineType: 'labor', laborServiceId: null })
      } else {
        await createQuoteLineItem(quoteId, {
          ...baseData,
          lineType: 'bicycle',
          bicycleId: null,
          bicycleBrand: null,
          bicycleModel: null,
          bicycleYear: null,
          bicycleColor: null,
          bicycleFrameSize: null,
        })
      }

      onClose()
      onAdded()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to add line item')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />

      {/* Dialog */}
      <div className="relative w-full max-w-md rounded-xl bg-white p-6 shadow-xl">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Add Line Item</h2>

        {error && (
          <div className="mb-3 rounded-lg bg-red-50 p-3 text-sm text-red-700">{error}</div>
        )}

        <form onSubmit={handleSubmit} className="space-y-3">
          {/* Line Type */}
          <div>
            <label className="block text-xs font-medium text-gray-600 mb-1">Type</label>
            <select
              value={lineType}
              onChange={(e) => setLineType(e.target.value as 'part' | 'labor' | 'bicycle')}
              className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none"
            >
              <option value="part">Part</option>
              <option value="labor">Labor</option>
              <option value="bicycle">Bicycle</option>
            </select>
          </div>

          {/* Description */}
          <div>
            <label htmlFor="desc" className="block text-xs font-medium text-gray-600 mb-1">Description *</label>
            <input
              id="desc"
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Item description..."
              className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none"
            />
          </div>

          {/* Quantity & Unit Price */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label htmlFor="qty" className="block text-xs font-medium text-gray-600 mb-1">Quantity *</label>
              <input
                id="qty"
                type="number"
                min={1}
                value={quantity}
                onChange={(e) => setQuantity(e.target.value)}
                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label htmlFor="price" className="block text-xs font-medium text-gray-600 mb-1">Unit Price (€) *</label>
              <input
                id="price"
                type="number"
                step="0.01"
                min={0}
                value={unitPriceNet}
                onChange={(e) => setUnitPriceNet(e.target.value)}
                placeholder="0.00"
                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none"
              />
            </div>
          </div>

          {/* VAT Rate */}
          <div>
            <label htmlFor="vat" className="block text-xs font-medium text-gray-600 mb-1">VAT Rate</label>
            <select
              id="vat"
              value={vatRateId}
              onChange={(e) => setVatRateId(e.target.value)}
              className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none"
            >
              {vatRates.map((vr) => (
                <option key={vr.id} value={vr.id}>{vr.label}</option>
              ))}
            </select>
          </div>

          {/* Discount */}
          <div>
            <label htmlFor="discount" className="block text-xs font-medium text-gray-600 mb-1">Discount (%)</label>
            <input
              id="discount"
              type="number"
              min={0}
              max={100}
              step={0.1}
              value={discountPercent}
              onChange={(e) => setDiscountPercent(e.target.value)}
              placeholder="0"
              className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none"
            />
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              disabled={submitting}
              className="rounded-lg border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting || !description || !unitPriceNet}
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {submitting ? 'Adding...' : 'Add Item'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/** Generate a unique ID for optimistic UI updates.
 * Works in both browser and Node.js without crypto.randomUUID(). */
export function generateId(): string {
  return Math.random().toString(36).substring(2) + Date.now().toString(36)
}

/** Format cents (integer) to Euro string with 2 decimal places. */
export function formatCentsToEuro(cents: number): string {
  return `€${(cents / 100).toFixed(2)}`
}

